if($action==='save_answer'&&$_SERVER['REQUEST_METHOD']==='POST'){ $u=role('Siswa');$rid=(int)$_POST['result'];$qid=(int)$_POST['question'];$answer=trim($_POST['answer']??'');$own=q('SELECT r.id FROM exam_results r JOIN students s ON s.id=r.student_id WHERE r.id=? AND s.user_id=? AND r.status="in_progress"',[$rid,$u['id']])->fetch();if(!$own){header('Content-Type: application/json');echo json_encode(['ok'=>false]);exit;}q('INSERT INTO answers(result_id,question_id,answer_text) VALUES(?,?,?) ON DUPLICATE KEY UPDATE answer_text=VALUES(answer_text)',[$rid,$qid,$answer]);header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;}
