if($action==='flag_answer'&&$_SERVER['REQUEST_METHOD']==='POST'){$u=role('Siswa');$rid=(int)$_POST['result'];$qid=(int)$_POST['question'];$flagged=(int)($_POST['flagged']??0);$own=q('SELECT r.id FROM exam_results r JOIN students s ON s.id=r.student_id WHERE r.id=? AND s.user_id=? AND r.status="in_progress"',[$rid,$u['id']])->fetch();if(!$own){header('Content-Type: application/json');echo json_encode(['ok'=>false]);exit;}q('INSERT INTO answers(result_id,question_id,flagged) VALUES(?,?,?) ON DUPLICATE KEY UPDATE flagged=?',[$rid,$qid,$flagged,$flagged]);header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;}
